import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { recsAPI } from '../utils/api';
import {
  ShieldCheck,
  ShieldAlert,
  ChevronDown,
  ChevronUp,
  Zap,
} from 'lucide-react';
import './ProductDetail.css';

export default function ProductDetail() {
  const { id } = useParams();
  const asin = id;

  const [product, setProduct] = useState(null);
  const [similar, setSimilar] = useState([]);
  const [trustCheck, setTrustCheck] = useState(null);
  const [loading, setLoading] = useState(true);
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [threshold, setThreshold] = useState(0.5);

  useEffect(() => {
    if (!asin) return;

    setLoading(true);

    Promise.all([
      recsAPI.getTrust(asin),
      recsAPI.getSimilar(asin, 6, 0.3),
    ])
      .then(([trustRes, simRes]) => {
        const trustData = trustRes.data || null;
        const similarData = simRes.data || [];

        setTrustCheck(trustData);
        setProduct(trustData);
        setSimilar(Array.isArray(similarData) ? similarData : []);
      })
      .catch((err) => {
        console.error('Product detail error:', err);
        setProduct(null);
        setTrustCheck(null);
        setSimilar([]);
      })
      .finally(() => setLoading(false));
  }, [asin]);

  useEffect(() => {
    if (!asin) return;

    recsAPI.getTrust(asin)
      .then((r) => setTrustCheck(r.data))
      .catch((err) => console.error('Trust refresh error:', err));
  }, [threshold, asin]);

  if (loading) {
    return (
      <div className="loading-center">
        <div className="spinner" />
      </div>
    );
  }

  if (!product || product.error) {
    return <div className="container">Product not found</div>;
  }

  const trust = product.trust || product || {};
  const finalTrustScore =
    trust.final_trust_score ??
    product.final_trust_score ??
    0;

  const isTrusty =
    trustCheck?.rl_decision?.is_trustworthy ??
    (finalTrustScore >= threshold);

  return (
    <div className="product-detail page-enter">
      <div className="container">
        <h1 className="detail-title">{product.title || 'Product'}</h1>

        <div className="trust-check-panel card">
          <div className="tcp-header">
            {isTrusty ? (
              <ShieldCheck color="green" />
            ) : (
              <ShieldAlert color="red" />
            )}
            <h3>Trust Verdict</h3>
          </div>

          <div className="tcp-scores">
            <p>ASIN: {product.asin || asin}</p>
            <p>Rating: {product.rating ?? 'N/A'}</p>
            <p>Final Trust: {(finalTrustScore * 100).toFixed(1)}%</p>
          </div>

          <div>
            <label>Threshold: {(threshold * 100).toFixed(0)}%</label>
            <input
              type="range"
              min="0"
              max="1"
              step="0.05"
              value={threshold}
              onChange={(e) => setThreshold(parseFloat(e.target.value))}
            />
          </div>

          <button
            type="button"
            onClick={() => setShowBreakdown(!showBreakdown)}
            className="btn btn-ghost"
          >
            {showBreakdown ? <ChevronUp /> : <ChevronDown />}
            Toggle Breakdown
          </button>

          {showBreakdown && (
            <pre style={{ whiteSpace: 'pre-wrap', overflowX: 'auto' }}>
              {JSON.stringify(trustCheck || product, null, 2)}
            </pre>
          )}
        </div>

        <div className="similar-section">
          <h2>
            <Zap /> Similar Products
          </h2>

          {similar.length === 0 ? (
            <p>No similar products found</p>
          ) : (
            <div className="grid-3">
              {similar.map((p, i) => (
                <Link
                  key={p.asin || i}
                  to={`/products/${p.asin}`}
                  className="card product-card"
                  style={{ textDecoration: 'none', color: 'inherit' }}
                >
                  <h3>{p.title || 'Untitled Product'}</h3>

                  <p>
                    <strong>ASIN:</strong> {p.asin || 'N/A'}
                  </p>

                  <p>
                    <strong>Rating:</strong> {p.rating ?? 'N/A'}
                  </p>

                  <p>
                    <strong>Trust:</strong>{' '}
                    {((p.final_trust_score || 0) * 100).toFixed(1)}%
                  </p>
                </Link>
              ))}
            </div>
          )}
        </div>

        <Link to="/products" className="btn btn-ghost">
          Back
        </Link>
      </div>
    </div>
  );
}
